#!/usr/bin/env node
// Playbook cleanup script — sets Playbook_Active=false for inactive/cancelled members
// Run from your nutrition-ai folder: node scripts/playbook-cleanup.mjs

import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))

// Load .env.local
const envFile = path.join(__dirname, '..', '.env.local')
const env = fs.readFileSync(envFile, 'utf8')
for (const line of env.split('\n')) {
  const [key, ...rest] = line.split('=')
  if (key && rest.length) process.env[key.trim()] = rest.join('=').trim()
}

const TOKEN = process.env.AIRTABLE_TOKEN
const BASE_ID = process.env.AIRTABLE_BASE_ID
const TABLE = 'Clients'

if (!TOKEN || !BASE_ID) {
  console.error('Missing AIRTABLE_TOKEN or AIRTABLE_BASE_ID in .env.local')
  process.exit(1)
}

