async function airtableFetch(url, options = {}) {
  const res = await fetch(url, {
    ...options,
    headers: {
      Authorization: `Bearer ${TOKEN}`,
      'Content-Type': 'application/json',
      ...(options.headers || {})
    }
  })
  if (!res.ok) {
    const text = await res.text()
    throw new Error(`Airtable ${res.status}: ${text}`)
  }
  return res.json()
}

async function getAllAirtableRecords() {
  const records = []
  let offset = null
  let page = 0

  do {
    const params = new URLSearchParams({ 'fields[]': ['Email', 'Playbook_Active'], pageSize: '100' })
    if (offset) params.set('offset', offset)

    const data = await airtableFetch(`https://api.airtable.com/v0/${BASE_ID}/${TABLE}?${params}`)
    page++
    process.stdout.write(`\r  Fetched page ${page} (${records.length + data.records.length} records)...`)

    for (const rec of data.records) {
      const email = (rec.fields?.Email || '').trim().toLowerCase()
      if (email) records.push({ id: rec.id, email, playbook: rec.fields?.Playbook_Active })
    }

    offset = data.offset || null
    if (offset) await new Promise(r => setTimeout(r, 200))
  } while (offset)

  console.log('')
  return records
}

async function batchUpdate(recordIds) {
  // Airtable allows max 10 records per PATCH request
  const chunks = []
  for (let i = 0; i < recordIds.length; i += 10) {
    chunks.push(recordIds.slice(i, i + 10))
  }

  let updated = 0
  for (const chunk of chunks) {
    await airtableFetch(`https://api.airtable.com/v0/${BASE_ID}/${TABLE}`, {
      method: 'PATCH',
      body: JSON.stringify({
        records: chunk.map(id => ({ id, fields: { Playbook_Active: false } }))
      })
    })
    updated += chunk.length
    process.stdout.write(`\r  Updated ${updated}/${recordIds.length}...`)
    await new Promise(r => setTimeout(r, 250))
  }
  console.log('')
}

async function main() {
  console.log('=== Playbook Cleanup — Deactivate Inactive/Cancelled Members ===')
  console.log(`Emails to deactivate (from CSV): ${DEACTIVATE_EMAILS.size}`)

  console.log('\nFetching Airtable records...')
  const allRecords = await getAllAirtableRecords()
  console.log(`Total Airtable records: ${allRecords.length}`)

  // Find records that are currently marked Playbook_Active=true but shouldn't be
  const toDeactivate = allRecords.filter(r =>
    DEACTIVATE_EMAILS.has(r.email) && r.playbook === true
  )

  // Also find records marked active that aren't in the CSV at all (not even inactive)
  const allCsvEmails = DEACTIVATE_EMAILS
  const toDeactivateNotInCsv = allRecords.filter(r =>
    !allCsvEmails.has(r.email) && r.playbook === true
  )

  console.log(`\nCurrently marked Playbook_Active=true but should be false: ${toDeactivate.length}`)
  console.log(`Marked active but not in Playbook CSV at all: ${toDeactivateNotInCsv.length}`)

  const allToFix = [...toDeactivate, ...toDeactivateNotInCsv]
  console.log(`Total to fix: ${allToFix.length}`)

  if (allToFix.length === 0) {
    console.log('\n✅ Nothing to fix — all Playbook flags look correct!')
    return
  }

  // Save list for reference
  fs.writeFileSync(
    path.join(__dirname, 'deactivated-members.txt'),
    allToFix.map(r => r.email).join('\n')
  )
  console.log('\nSaved full list to scripts/deactivated-members.txt')

  console.log(`\nSetting Playbook_Active=false for ${allToFix.length} records...`)
  await batchUpdate(allToFix.map(r => r.id))

  console.log(`\n✅ Done! ${allToFix.length} records updated.`)
  console.log('Active Playbook members are untouched.')
}

main().catch(err => {
  console.error('Error:', err.message)
  process.exit(1)
})
